"""Realistic OrcaSlicer G-code snippets for the plate-parts tests.

Modelled on production G-code (spike 2026-10-29): the header defines every
object on the plate with ``EXCLUDE_OBJECT_DEFINE NAME=Object_<N>_id_<i>_copy_0``
and the body wraps each object's moves in ``; printing object …`` comments.
"""

_HEADER = """; HEADER_BLOCK_START
; generated by OrcaSlicer 2.3.0 on 2026-10-29 at 09:12:44
; total layer number: 120
; estimated printing time (normal mode) = 1h 2m 3s
; HEADER_BLOCK_END

; THUMBNAIL_BLOCK_START
; thumbnail begin 16x16 64
; iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAC0lEQVR4nGNgGAWDEQAAAhAAAQ==
; thumbnail end
; THUMBNAIL_BLOCK_END

; CONFIG_BLOCK_START
; printer_model = Voron 2.4 350
; CONFIG_BLOCK_END

M73 P0 R62
M190 S60
M109 S215
"""


def _define(object_id: int, index: int) -> str:
    x = 40 + index * 25
    return (
        f"EXCLUDE_OBJECT_DEFINE NAME=Object_{object_id}_id_{index}_copy_0 CENTER={x}.5,80.25 "
        f"POLYGON=[[{x - 10}.1,70.0],[{x + 10}.9,70.0],[{x + 10}.9,90.5],[{x - 10}.1,90.5],[{x - 10}.1,70.0]]\n"
    )


def _body(object_id: int, index: int) -> str:
    name = f"Object_{object_id}_id_{index}_copy_0"
    return (
        f"; printing object {name}\n"
        f"EXCLUDE_OBJECT_START NAME={name}\n"
        "G1 X50.123 Y60.456 E.02153\n"
        "G1 X51.5 Y60.456 E.04722\n"
        f"EXCLUDE_OBJECT_END NAME={name}\n"
        f"; stop printing object {name}\n"
    )


def plate_gcode(object_ids: list[int], *, define: bool = True, comments: bool = True) -> bytes:
    """Build the G-code of one plate printing ``object_ids``.

    Args:
        object_ids: 3MF bundle object IDs on the plate.
        define: Emit the ``EXCLUDE_OBJECT_DEFINE`` header lines.
        comments: Emit the ``; printing object`` body comments.

    Returns:
        G-code bytes.
    """
    text = _HEADER
    if define:
        text += "".join(_define(object_id, index) for index, object_id in enumerate(object_ids))
    text += "; layer num/total_layer_count: 1/120\nG1 Z.2 F720\n"
    for index, object_id in enumerate(object_ids):
        text += _body(object_id, index) if comments else "G1 X10 Y10 E.1\n"
    text += "; EXECUTABLE_BLOCK_END\nM84\n"
    return text.encode()
